package snapshots

import (
	"crypto/sha256"
	"sync"
)

// Cache only small metadata reads, rather than whole 128KiB decoded blocks.
// Cross-open hits first read/hash the CURRENT complete compressed block. A
// reader-local signature has the same lifetime as its existing decoded cache.
const historyHeaderPrefixBytes = 4096
const historyHeaderCacheEntries = 131072
const historyHeaderCacheBytes = 32 << 20

type historyHeaderKey struct {
	digest      [sha256.Size]byte
	decodedSize uint64
	offset      uint32
	length      uint32
}
type historyHeaderCache struct {
	mu                 sync.Mutex
	entries            map[historyHeaderKey][]byte
	fifo               []historyHeaderKey
	next, count, bytes int
	limit              int
	byteLimit          int
}

var sharedHistoryHeaderCache = &historyHeaderCache{limit: historyHeaderCacheEntries, byteLimit: historyHeaderCacheBytes}

func (c *historyHeaderCache) get(key historyHeaderKey, dst []byte) bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	v, ok := c.entries[key]
	if !ok || len(v) != len(dst) {
		return false
	}
	copy(dst, v)
	return true
}
func (c *historyHeaderCache) put(key historyHeaderKey, data []byte) {
	if c == nil || c.limit <= 0 || len(data) > historyHeaderPrefixBytes {
		return
	}
	budget := c.byteLimit
	if budget <= 0 {
		budget = historyHeaderCacheBytes
	}
	if len(data) > budget {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if _, ok := c.entries[key]; ok {
		return
	}
	if c.entries == nil {
		c.entries = make(map[historyHeaderKey][]byte)
		c.fifo = make([]historyHeaderKey, c.limit)
	}
	for c.count > 0 && (c.count >= c.limit || c.bytes+len(data) > budget) {
		old := c.fifo[c.next]
		c.bytes -= len(c.entries[old])
		delete(c.entries, old)
		c.next = (c.next + 1) % c.limit
		c.count--
	}
	c.entries[key] = append([]byte(nil), data...)
	c.bytes += len(data)
	c.fifo[(c.next+c.count)%c.limit] = key
	c.count++
}

type historyReadSignature struct {
	index  int
	digest [sha256.Size]byte
	size   uint64
}

func (r *compressedBlockReader) metadataSignature(i int, comp []byte, size uint64) historyReadSignature {
	v := historyReadSignature{index: i, digest: sha256.Sum256(comp), size: size}
	for j := range r.metadataSignatures {
		if r.metadataSignatures[j].index == i {
			r.metadataSignatures[j] = v
			return v
		}
	}
	if len(r.metadataSignatures) < cbCacheBlocks {
		r.metadataSignatures = append(r.metadataSignatures, v)
	} else {
		r.metadataSignatures[r.metadataNext] = v
		r.metadataNext = (r.metadataNext + 1) % cbCacheBlocks
	}
	return v
}
func metadataReadKey(v historyReadSignature, off uint64, n int) historyHeaderKey {
	return historyHeaderKey{digest: v.digest, decodedSize: v.size, offset: uint32(off), length: uint32(n)}
}

// Caller holds r.mu. Neither returned data nor caller buffers alias the cache.
func (r *compressedBlockReader) readHeaderPrefix(p []byte, off uint64, i int) (int, error) {
	intra := off - r.table[i].uncompressedStart
	for _, e := range r.cache {
		if e.idx == i {
			key := metadataReadKey(e.signature, intra, len(p))
			n := copy(p, e.bytes[intra:])
			if e.signature.size != 0 {
				r.prefixCache.put(key, p[:n])
			}
			return n, nil
		}
	}
	for _, v := range r.metadataSignatures {
		if v.index == i && r.prefixCache.get(metadataReadKey(v, intra, len(p)), p) {
			return len(p), nil
		}
	}
	comp, expected, err := r.readCompressedBlock(i)
	if err != nil {
		return 0, err
	}
	sig := r.metadataSignature(i, comp, expected)
	key := metadataReadKey(sig, intra, len(p))
	if r.prefixCache.get(key, p) {
		return len(p), nil
	}
	decoded, err := r.decodeBlock(i, comp, expected)
	if err != nil {
		return 0, err
	}
	n := copy(p, decoded[intra:])
	r.prefixCache.put(key, p[:n])
	return n, nil
}

